	ResultSet results = null;

	String query =
		"select r.ID_BENEF, s.NUM_IDENTITE, s.NOM, s.PRENOM, s.TYPE_IDENTITE, s.TEL, s.ADRESSE, s.MOTIFMAD "
			+ "from MAD_ASSOCIATION r, MAD_BENEFICIAIRE s "
