			+ "r.DATE_SUPPRESSION is null and r.ID_BENEF = s.ID_BENEF";

	Log.info("Exécution de la requête pour l'utilisateur ID: " + idClient);

	try (PreparedStatement stmt = connexion.prepareStatement(query)) {
	    // Utilisation de paramètres préparés pour éviter l'injection SQL
	    stmt.setString(1, idClient);

	    stmt.execute();
	    results = stmt.getResultSet();

