		madBenef.setNumIdentite(results.getString(NUMIDENTITE));
		madBenef.setNom(results.getString("NOM"));
		madBenef.setPrenom(results.getString(PRENOM));
		madBenef.setTypeIdentite(results.getString(TYPEDIDENTITE));
		madBenef.setAdresse(results.getString(ADRESSE));
		madBenef.setTel(results.getString("TEL"));
		madBenef.setMotifMAD(results.getString(MOTIFMAD));
		madBenef.setIdBenef(results.getString(IDBENEF));
		liste.add(madBenef);
	    }
	} catch (Exception e) {
	    Log.error("Erreur lors de la récupération des bénéficiaires", e);
	    throw e; // Remonter l'exception pour permettre une gestion appropriée
	} finally {
	    if (results != null) {
		try {
		    results.close();
		} catch (SQLException e) {
		    Log.error(MSGERROR, e);
		}
	    }
	}

	return liste;
    }

