		blcCompte = reponseSolde.getNodeAsString("GSC/GSCRSPONSE/SoldeDataReponse/BLC_COMPTE");
		saisieArret = reponseSolde.getNodeAsString("GSC/GSCRSPONSE/SoldeDataReponse/SAISIE_ARRET");
		retourSolde.setSaisieArret(saisieArret);
		retourSolde.setBlcCompte(blcCompte);
	    }

	} catch (CompteException e) {
	    Log.info("Erreur lors de l'invocation du service Compte " + e.getMessage());

	} catch (Exception e) {
	    Log.info("message d'erreur fonction getCodePops " + e.getMessage());

	}
	return retourSolde;
