    private static List<MadMad> ListMadIsAttente(List<MadMad> liste, Connection connexionEbankInterface,
	    Connection connexionEbankDirect) throws SQLException {
	final List<MadMad> listeMadEnAttente = new ArrayList<>();
	Log.info("debut liste MAd attente ");

	try {
	    for (MadMad mad : liste) {
		traiterMad(mad, connexionEbankInterface, connexionEbankDirect, listeMadEnAttente);
	    }
	} catch (Exception e) {
	    Log.info("exeption levée lors invoker function DTV VIREMENT.GETMADEBANKINGISREGLE " + e.getMessage());
	}
	return listeMadEnAttente;
    }

    private static void traiterMad(MadMad mad, Connection connexionEbankInterface, Connection connexionEbankDirect,
	    List<MadMad> listeMadEnAttente) throws SQLException {

	String etat = verifierEtatMad(mad, connexionEbankInterface);

	if (etat.equals("004")) {
	    listeMadEnAttente.add(mad);
	    mad.setMadEtat(etat);
	}

	if (etat.equals("000") || etat.equals("003") || etat.equals("004")) {
	    mettreAJourEtatMad(mad.getReference(), etat, connexionEbankDirect);
	}
    }

    private static String verifierEtatMad(MadMad mad, Connection connexion) throws SQLException {
	String etat = "";
	ResultSet results = null;
	CallableStatement cs = null;

	try {
	    cs = connexion.prepareCall("{? = call VIREMENT.GETMADEBANKINGISREGLE(?)}");
	    cs.registerOutParameter(1, OracleTypes.CURSOR);
	    cs.setString(2, mad.getReference());
	    cs.execute();

	    results = (ResultSet) cs.getObject(1);
	    etat = determinerEtatMad(results);
	} finally {
	    fermerRessources(results, cs);
	}

	return etat;
    }

    private static String determinerEtatMad(ResultSet results) throws SQLException {
	if (results == null) {
	    return "";
	}

	while (results.next()) {
	    String valeur = results.getString(2);

	    if (valeur == null) {
		return "004";
	    }

	    if ("1".equals(valeur)) {
		return "000";
	    }

	    if ("0".equals(valeur)) {
		return "003";
	    }
	}

	return "";
    }

    private static void fermerRessources(ResultSet rs, CallableStatement cs) {
	if (rs != null) {
	    try {
		rs.close();
	    } catch (SQLException e) {
		Log.info("Erreur lors de la fermeture du ResultSet: " + e.getMessage());
	    }
	}

	if (cs != null) {
	    try {
		cs.close();
	    } catch (SQLException e) {
		Log.info("Erreur lors de la fermeture du CallableStatement: " + e.getMessage());
	    }
	}
    }

    private static void mettreAJourEtatMad(String reference, String etat, Connection connexion) throws SQLException {

	final String SQL_UPDATE_MAD = "UPDATE MAD_MAD SET CODE_ETAT = ? WHERE REFERENCE_MAD = ?";

	try (PreparedStatement stmt = connexion.prepareStatement(SQL_UPDATE_MAD)) {
	    // Liaison des paramètres pour prévenir l'injection SQL
	    stmt.setString(1, etat);
	    stmt.setString(2, reference);

	    int rowsUpdated = stmt.executeUpdate();

	    // Vérification optionnelle pour s'assurer que la mise à jour a bien été effectuée
	    if (rowsUpdated == 0) {
		Log.warn("Aucune MAD avec la référence: {} n'a été mise à jour", reference);
	    }
	}
    }

