    private static void traiterMad(MadMad mad, Connection connexionEbankInterface, Connection connexionEbankDirect)
	    throws SQLException {

	String etat = determinerEtatMad(mad, connexionEbankInterface);

	if (etat.equals("000") || etat.equals("003") || etat.equals("004")) {
	    mettreAJourEtatMad(mad, etat, connexionEbankDirect);
	}
    }

    private static String determinerEtatMad(MadMad mad, Connection connexion) throws SQLException {
	String etat = "";

	try (CallableStatement cs = connexion.prepareCall("{? = call VIREMENT.GETMADEBANKINGISREGLE(?)}")) {
	    cs.registerOutParameter(1, OracleTypes.CURSOR);
	    cs.setString(2, mad.getReference());
	    cs.execute();

	    try (ResultSet results = (ResultSet) cs.getObject(1)) {
		etat = extraireEtatDuResultat(results);
	    }
	}

	return etat;
    }

    private static String extraireEtatDuResultat(ResultSet results) throws SQLException {
	while (results.next()) {
	    String valeur = results.getString(2);

	    if (valeur == null) {
		return "004"; // En attente de règlement
	    }

	    if ("1".equals(valeur)) {
		return "000"; // Réglée
	    }

	    if ("0".equals(valeur)) {
		return "003"; // Annulée
	    }
	}

	return "";
    }

