    public static boolean isDuplicateTransaction(Connection conn, String transactionKey) throws SQLException {
	long start = System.currentTimeMillis();

	String selectSql = "SELECT DATE_CREATION FROM MAD_TRANSACTION_LOCK WHERE TRANSACTION_KEY = ? FOR UPDATE";
	String deleteSql = "DELETE FROM MAD_TRANSACTION_LOCK WHERE TRANSACTION_KEY = ?";
	String insertSql = "INSERT INTO MAD_TRANSACTION_LOCK (TRANSACTION_KEY, DATE_CREATION) VALUES (?, SYSDATE)";

	Timestamp dateCreation = getTransactionDate(conn, selectSql, transactionKey);

	// Si aucune entrée : insérer directement
	if (dateCreation == null) {
	    Log.info("DATE CREATION is NULL");
	    insertTransactionKey(conn, insertSql, transactionKey);
	    logDuration(start);
	    return false;
	}

	// Si doublon dans la fenêtre TTL
	long diffMillis = System.currentTimeMillis() - dateCreation.getTime();
	Log.info("Difference en (ms): "+diffMillis);
	if (diffMillis <= TTL_MILLIS) {
	    logDuration(start);
	    return true;
	}

	Log.info("supprimer puis inserer");
	// Sinon : suppression puis réinsertion
	deleteTransactionKey(conn, deleteSql, transactionKey);
	insertTransactionKey(conn, insertSql, transactionKey);

	logDuration(start);
	return false;
    }

    private static Timestamp getTransactionDate(Connection conn, String selectSql,
	    String transactionKey)
	    throws SQLException {
	Log.info("Vérification KEY_AVANT_SELECT = "
		+ transactionKey);
	try (PreparedStatement psSelect = conn.prepareStatement(selectSql)) {
	    psSelect.setString(1, transactionKey);
	    try (ResultSet rs = psSelect.executeQuery()) {
		if (rs.next()) {
		    return rs.getTimestamp("DATE_CREATION");
		}
	    }
	}
	return null;
    }

    private static void deleteTransactionKey(Connection conn, String deleteSql, String transactionKey)
	    throws SQLException {
	try (PreparedStatement psDel = conn.prepareStatement(deleteSql)) {
	    psDel.setString(1, transactionKey);
	    psDel.executeUpdate();
	}
    }

    private static void insertTransactionKey(Connection conn, String insertSql,
	    String transactionKey)
	    throws SQLException {
	Log.info("Vérification AVANT_INSERT = " + transactionKey);
	try (PreparedStatement psInsert = conn.prepareStatement(insertSql)) {
	    psInsert.setString(1, transactionKey);
	    psInsert.executeUpdate();
	}
    }

    private static void logDuration(long start) {
	long end = System.currentTimeMillis();
	Log.info("Temps écoulé isDuplicateTransaction() en ms : " + (end - start));
    }
