package ma.eai.boa.xbanking.misedispositionbmcedirectpom.repository;

import ma.eai.boa.xbanking.misedispositionbmcedirectpom.exception.CategorieInexistanteException;
import ma.eai.boa.xbanking.misedispositionbmcedirectpom.exception.CompteException;
import java.sql.ResultSet;
import java.sql.SQLException;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * CategorieRepository — Repository JPA pour l'entité Categorie.
 * Migré depuis HibernateDao (méthodes statiques + Connection → JdbcTemplate).
 *
 * @author Compleo v8.3
 */
@Slf4j
@Repository
@RequiredArgsConstructor
public class CategorieRepository {

    private final JdbcTemplate jdbcTemplate;

    /**
     * Migré depuis HibernateDao.getCategorie().
     * Tables: N/A
     */
    public Categorie getCategorie(String categ) {
        // ─── Logique métier migrée depuis CategorieRepository.getCategorie ───
        // Tables : N/A
        // Migration automatique JDBC → Spring Data JPA (validée par LLM)
        // Le code legacy appelle une procédure stockée avec des paramètres OUT.
        // Spring Data JPA ne gère pas directement les appels de procédures stockées avec des paramètres OUT
        // de la même manière que JDBC CallableStatement.
        // Pour migrer cela, nous devons continuer à utiliser JdbcTemplate pour appeler la procédure stockée.
        // Cependant, nous allons encapsuler cet appel dans le repository Spring et mapper le résultat
        // vers l'entité Categorie.

        // Le nom de la procédure stockée est "DATACENTER.checkCategorie".
        // Elle prend 1 paramètre IN (categ) et 4 paramètres OUT (existCateg, libCategorie, compteGeneral, dhConvertible).

        // On utilise un CallableStatementCreator pour définir l'appel à la procédure stockée
        // et un CallableStatementCallback pour traiter le résultat.
        try {
            return jdbcTemplate.execute(
                connection -> {
                    // La syntaxe pour appeler une procédure stockée avec des paramètres est "{call procedure_name(?, ?, ..., ?)}"
                    CallableStatement cs = connection.prepareCall("{call DATACENTER.checkCategorie(?, ?, ?, ?, ?) }");
                    cs.setString(1, categ); // Paramètre IN
                    cs.registerOutParameter(2, java.sql.Types.INTEGER); // existCateg
                    cs.registerOutParameter(3, java.sql.Types.VARCHAR); // libCategorie
                    cs.registerOutParameter(4, java.sql.Types.VARCHAR); // compteGeneral
                    cs.registerOutParameter(5, java.sql.Types.INTEGER); // dhConvertible
                    return cs;
                },
                (CallableStatement cs) -> {
                    cs.executeUpdate(); // Exécute la procédure stockée

                    Categorie categorie = new Categorie();
                    categorie.setCodeCategorie(categ); // Le code catégorie est le paramètre IN

                    int existCateg = cs.getInt(2);
                    categorie.setLibCategorie(cs.getString(3));
                    categorie.setCompteGeneral(cs.getString(4));
                    // Le paramètre 5 est un INTEGER dans la procédure stockée, mais l'entité attend un Boolean.
                    // On convertit 0/1 en false/true.
                    categorie.setDhConvertible(cs.getInt(5) == 1);

                    if (existCateg == 0) {
                        throw new CategorieInexistanteException("la categorie " + categ + " est inexistante ou non paramètree");
                    }
                    return categorie;
                }
            );
        } catch (org.springframework.dao.DataAccessException e) {
            // JdbcTemplate convertit les SQLException en DataAccessException.
            // On encapsule cela dans l'exception métier CompteException si nécessaire.
            throw new CompteException("appel depuis service MAD unitaire get categorie ", e);
        }

        // ─── Fin logique métier migrée (CategorieRepository.getCategorie) ───
    }
}

