	private Envelope oppositionCarte(OppositionCarteEntity entity) throws ParsingException {


		Log.info("OppositionCarteService: Debut oppositionCarte");

		Envelope envelopeOut = new Envelope();

		try {

			Envelope retourMon = MonetiqueService.callService(entity);
			if (retourMon == null) {

				WriteFlux.ecrireString(envelopeOut, Constants.FLUX, "code", Constants.RESPONSE_CODE_ERROR, "");
				WriteFlux.ecrireString(envelopeOut, Constants.FLUX, Constants.MESSAGE, Constants.RESPONSE_MSG_ERROR_02, "");

			} else {

				MonetiqueAnswer objectAnswer = MonetiqueService.getDataFromEnvlop(retourMon);

				if (objectAnswer == null) {

					WriteFlux.ecrireString(envelopeOut, Constants.FLUX, "code", Constants.RESPONSE_CODE_ERROR, "");
					WriteFlux.ecrireString(envelopeOut, Constants.FLUX, Constants.MESSAGE, Constants.RESPONSE_MSG_ERROR_03, "");
				}

				else {
					WriteFlux.ecrireString(envelopeOut, Constants.FLUX, "code", Constants.RESPONSE_CODE_OK, "");
					WriteFlux.ecrireString(envelopeOut, Constants.FLUX, Constants.MESSAGE, Constants.RESPONSE_MSG_OK, "");
					WriteFlux.ecrireString(envelopeOut, Constants.FLUX, "NUMENR_NUM", objectAnswer.get_NUMENR_NUM(),
							"");
					WriteFlux.ecrireString(envelopeOut, Constants.FLUX, "ISO4", objectAnswer.get_ISO4(), "");
					WriteFlux.ecrireString(envelopeOut, Constants.FLUX, "ISO2", objectAnswer.get_ISO2(), "");
					WriteFlux.ecrireString(envelopeOut, Constants.FLUX, "ISO13", objectAnswer.get_ISO13(), "");

					Connection connexionEbankDirect = null;


					connexionEbankDirect = ebankdirectXA.getConnection();
					OppositionCarteDao.save(entity, connexionEbankDirect);


					String filePath = "OppositionCarte.html";
					String content = FileUtils.fileReader(filePath);
					// date now
					Date dateNow = new Date();
					// format Date & hour
					String Date = DateUtil.convertDateToString(dateNow, "dd-MM-yyyy");
					String heure = DateUtil.convertDateToString(dateNow, "HH:mm:ss");
					content = content.replace("Date_", Date);
					content = content.replace("Heure_", heure);

					content = content.replace("Num_carte_bancaire", entity.getNumCarte());
					content = content.replace("Num_compte", entity.getNumCompteFormat());
					content = content.replace("libelle_compte", entity.getLibelCompte());
					content = content.replace("Intitule_carte", entity.getLibelleCarte());
					content = content.replace("Nom_titulaire_carte", entity.getNomPorteur());

					String Subject = "Avis d'opération Opposition carte";

					// send mail
				    sendNotificationEmail(entity, connexionEbankDirect, content, dateNow, Subject);

				}
			}

		} catch (Throwable e) {

			if (Constants.getMyappmode() != Constants.ModeDEV.DEV) {
				Log.error("Error oppositionCarte 4: " + e.getMessage());
				Log.error(e);
			}
			Log.info(e.getMessage());
		}

		Log.info("OppositionCarteService: flux en sortie pour l'action : " + Parser.unmarshall(envelopeOut.toString()));

		return envelopeOut;
	}

    private static void sendNotificationEmail(OppositionCarteEntity entity, Connection connexionEbankDirect, String content,
	    Date dateNow, String Subject) throws IOException, SQLException, ParseException {
	boolean send = false;
	if (entity.getMail() != null || entity.getMail().length() != 0) {
		send = Mailer.send(entity.getMail(), Subject, content);
	}
	if (send) {
		Log.info("Mail sent !!");
		String[] idClient = entity.getIdClient().split("_");
		// Add new entry in NOTIF_EBANKING Table
		NotificationDao.addNotif(entity.getNumTiers(), idClient[0], idClient[1], entity.getCanal(),
				DateUtil.convertDateToString(dateNow, "yyyyMMddHHmm"), entity.getMail(), "Opposition carte",
				entity.getIdClient(), 1, connexionEbankDirect);

	} else {
		Log.info("Mail not sent !! to : " + entity.getMail());

	}
    }

