    private Envelope getListCarte(Envelope envIn) throws ParsingException, Exception {
	Envelope fluxInput1 = envIn;
	Envelope envOut = new Envelope();
	Log.info("flux IN Appel de EJB M2M liste Cartes: " + Parser.marshall(fluxInput1));

	Envelope envOutFinalCarte = WriteFlux.GetFluxCartesEJB(Parser.marshall(fluxInput1));
	Log.info("Testing the list");

	try {
	    int accountCount = envOutFinalCarte.getNodeAsList("flux").size() - 3;
	    Log.info("Account count: " + accountCount);

	    for (int j = 1; j <= accountCount; j++) {
		processAccount(envOut, envOutFinalCarte, j);
	    }
	    Log.info("Final envOut: " + envOut);
	} catch (Throwable e) {
	    Log.info("Caught error: " + e.getMessage());
	}

	Log.info("Function return: " + Parser.marshall(envOut));
	return envOut;
    }
    private void processAccount(Envelope envOut, Envelope envOutFinalCarte, int accountIndex) throws ParsingException {
	List<String> accountsListFromFlow = envOutFinalCarte.getNodeAsList(Constants.FLUXCOMPTE + accountIndex);
	int accountSize = accountsListFromFlow.size();
	Log.info("Account size: " + accountSize);

	if (accountSize > 3) {
	    addAccountNodes(envOut, accountIndex, accountsListFromFlow);
	    processCards(envOut, envOutFinalCarte, accountIndex, accountSize - 3);
	} else {
	    Log.info("No cards exist for this account.");
	    envOut.addNode(Constants.FLUXCOMPTE + accountIndex + Constants.NUMCOMPTE, accountsListFromFlow.get(0));
	}
	Log.info("envOut for account: " + envOut);
    }

    private void processCards(Envelope envOut, Envelope envOutFinalCarte, int accountIndex, int cardCount) throws ParsingException {
	int k = 0;
	for (int i = 1; i <= cardCount; i++) {
	    List<String> cardsListFromFlow = envOutFinalCarte.getNodeAsList(Constants.FLUXCOMPTE + accountIndex + Constants.CARTE + i);
	    String cardState = cardsListFromFlow.get(4);
	    Log.info("Card state: " + cardState);

	    if (!"Inactive".equals(cardState)) {
		k++;
		addCardNodes(envOut, accountIndex, k, cardsListFromFlow);
	    }
	    Log.info("envOut for card: " + envOut);
	}
    }

    private void addAccountNodes(Envelope envOut, int accountIndex, List<String> accountsListFromFlow) {
	envOut.addNode(Constants.FLUXCOMPTE + accountIndex + Constants.NUMCOMPTE, accountsListFromFlow.get(0));
	envOut.addNode(Constants.FLUXCOMPTE + accountIndex + "/NatureCompte", accountsListFromFlow.get(1));
	envOut.addNode(Constants.FLUXCOMPTE + accountIndex + "/NomSousc", accountsListFromFlow.get(2));
    }

    private void addCardNodes(Envelope envOut, int accountIndex, int cardIndex, List<String> cardsListFromFlow) {
	envOut.addNode(Constants.FLUXCOMPTE + accountIndex + Constants.CARTE + cardIndex + "/NumToken", cardsListFromFlow.get(0));
	envOut.addNode(Constants.FLUXCOMPTE + accountIndex + Constants.CARTE + cardIndex + "/LibelleCarte", cardsListFromFlow.get(1));
	envOut.addNode(Constants.FLUXCOMPTE + accountIndex + Constants.CARTE + cardIndex + "/NomPorteur", cardsListFromFlow.get(2));
	envOut.addNode(Constants.FLUXCOMPTE + accountIndex + Constants.CARTE + cardIndex + "/FinVal", cardsListFromFlow.get(3));
	envOut.addNode(Constants.FLUXCOMPTE + accountIndex + Constants.CARTE + cardIndex + "/Etat", cardsListFromFlow.get(4));
    }
