    // traitement
    // @SuppressWarnings("deprecation")
    public static Envelope traitement(Envelope envIn) throws Exception {
	Envelope envOut = new Envelope();

	// Determine action to be executed
	Action action = Action.fromValue(envIn.getNodeAsString(FLUX_ACTION));

	switch (action) {
	case UPDATE_EPARGNE_DOC_ID:
	    return handleUpdateEpargneDocId(envIn);
	case GET_EPARGNE_DOC_ID:
	    return handleGetEpargneDocId(envIn);
	case GETINFOTIERS:
	    return handleGetInfoTiers(envIn);
	case CONSULTER_VERSEMENTS_TST:
	    return handleConsulterVersementsTST(envIn);
	case GETCONTRAT_TST:
	    return handleConsulterContratTST(envIn);
	case CONSULTER_PRESTATION_TST:
	    return handleConsulterPrestationTST(envIn);
	case CONSULTER_CONTRAT_TST:
	    return handleConsulterContratTST(envIn);
	case GETCONTRAT:
	    return handleGetContrat(envIn);
	case CONSULTER_CONTRAT:
	    return handleConsulterContrat(envIn);
	case IMPRIMER_LIST_VERSEMENT:
	    return handleImprimerListVersement(envIn);
	case CONSULTER_VERSEMENTS:
	    return handleConsulterVersements(envIn);
	case IMPRIMER_LIST_PRESTATION:
	    return handleImprimerListPrestation(envIn);
	case CONSULTER_LIST_PRESTATIONS:
	    return handleConsulterListPrestations(envIn);
	case CONSULTER_RELEVE_SITUATION_TO_PDF:
	    return handleConsulterReleveSituationTOPDF(envIn);
	case CONSULTER_RELEVE_SITUATION:
	    return handleConsulterReleveSituation(envIn);
	default:
	      EaiLog.error("Unknown action: " + action);
	    throw new UnsupportedOperationException("Action not supported");
	}
    }
    private static Envelope handleUpdateEpargneDocId(Envelope envIn) throws Exception {
	String documentId = envIn.getNodeAsString(Constante.FLUX + "/documentId");
	String numContratToUpdate = envIn.getNodeAsString(Constante.FLUX + "/numContrat");
	Connection connexionEbankDirect = ebankdirect.getConnection();
	Envelope envelopeOut = new Envelope();

	try {
	    HibernateDao.updateDocumentId(connexionEbankDirect, numContratToUpdate, documentId);
	    WriteFlux.ecrireString(envelopeOut, Constante.FLUX, Constante.STATUS, Constante.STATUS_OK, "");
	} catch (SQLException exception) {
	      EaiLog.error(exception);
	    WriteFlux.ecrireString(envelopeOut, Constante.FLUX, Constante.STATUS, Constante.STATUS_KO, "");
	} finally {
	    closeConnection(connexionEbankDirect);
	}
	return envelopeOut;
    }
    private static Envelope handleGetEpargneDocId(Envelope envIn) throws Exception {
	String numContratToReturn = envIn.getNodeAsString(Constante.FLUX + "/numContrat");
	Connection ebankdirectConnection = ebankdirect.getConnection();
	Envelope envelopeIdDocOut = new Envelope();

	try {
	    String documentIdFromDb = HibernateDao.getDocumentByContrat(ebankdirectConnection, numContratToReturn);
	    WriteFlux.ecrireString(envelopeIdDocOut, Constante.FLUX, Constante.STATUS, Constante.STATUS_OK, "");
	    WriteFlux.ecrireString(envelopeIdDocOut, Constante.FLUX, Constante.DOCUMENT_ID, documentIdFromDb, "");
	} catch (SQLException exception) {
	      EaiLog.error(exception);
	    WriteFlux.ecrireString(envelopeIdDocOut, Constante.FLUX, Constante.STATUS, Constante.STATUS_KO, "");
	} finally {
	    closeConnection(ebankdirectConnection);
	}
	return envelopeIdDocOut;
    }
