    private static Envelope handleConsulterVersements(Envelope envIn) throws Exception {
	Envelope envOut = new Envelope();
	 EaiLog.info("début appel service ConsulterVersements " + envIn);
	String numContrat = envIn.getNodeAsString(FLUX_CONTRAT_NUM_CONTRAT);
	String typeContrat = envIn.getNodeAsString(FLUX_CONTRAT_TYPE_CONTRAT);

	int targetPage = Integer.parseInt(envIn.getNodeAsString("flux/pager/targetPage"));
	int pageSize = Integer.parseInt(envIn.getNodeAsString("flux/pager/pageSize"));

	try {
	    Contrat contrat = WebServiceRMA.consulterVersements(numContrat, Constante.PROFONDEUR);

	    List<VersementsList> listVersements = contrat.getListVersements();
	    int numPage = Math.max(targetPage, 1);
	    int idxD = (numPage - 1) * pageSize;
	    int idxF = Math.min(numPage * pageSize, listVersements.size());

	    int totalPage = (listVersements.size() + pageSize - 1) / pageSize;

	    if (idxF <= idxD) {
		idxD = Math.max(idxF - pageSize, 0);
	    }

	    List<VersementsList> paginatedList = recupererPlageListeVersements(listVersements, idxD, idxF);
	    contrat.setListVersements(paginatedList);
	    contrat.setLibelleProduit(typeContrat);

	    envOut = WriteFlux.writeFluxListVersements(contrat);
	    envOut.addNode("flux/contrat/total", String.valueOf(totalPage));

	     EaiLog.info("Successfully selected list of versements with pagination.");
	} catch (Exception e) {
	     EaiLog.error("Error in selecting list of versements: " + e.getMessage(), e);
	    envOut = WriteFlux.writeFluxMSG(Constante.codeErreurGetContrat, Constante.msgErreurGetContrat);
	}

	return envOut;
    }

