    private static Envelope handleConsulterReleveSituation(Envelope envIn) throws Exception {
	Envelope envOut = new Envelope();
	String numContrat = envIn.getNodeAsString("flux/releveDeSituation/numContrat");
	String exercice = envIn.getNodeAsString("flux/releveDeSituation/exercice");
	String typeContrat = envIn.getNodeAsString("flux/releveDeSituation/typeContrat");

	try {
	    ReleveDeSituation releveDeSituation = WebServiceRMA.consulterReleveDeSituation(numContrat, exercice);

	    // Ensure correct method names for summing versements
	    double sommeVersementsExceptionnels = releveDeSituation.getVersements().stream()
		    .mapToDouble(versement -> versement.getVersementExceptionnel())  // Using available method
		    .sum();

	    double sommeVersementsPeriodiques = releveDeSituation.getVersements().stream()
		    .mapToDouble(versement -> versement.getVersementPeriodique())  // Using available method
		    .sum();

	    double sommeTotaleVersement = releveDeSituation.getVersements().stream()
		    .mapToDouble(versement -> versement.getTotalVersementsMois())  // Using available method
		    .sum();

	    releveDeSituation.setSommeVersementsExceptionnels(sommeVersementsExceptionnels);
	    releveDeSituation.setSommeVersementsPeriodiques(sommeVersementsPeriodiques);
	    releveDeSituation.setSommeTotaleVersement(sommeTotaleVersement);

	    envOut = WriteFlux.writeFluxReleveDeSituation(releveDeSituation, numContrat, typeContrat);

	     EaiLog.info("Releve de Situation retrieved successfully.");
	} catch (Exception e) {
	     EaiLog.error("Error in retrieving Releve de Situation: " + e.getMessage(), e);
	    envOut = WriteFlux.writeFluxMSG(Constante.codeErreurGetContrat, Constante.msgErreurGetContrat);
	}

	return envOut;
    }


    private static void closeConnection(Connection connection) {
	try {
	    if (connection != null && !connection.isClosed()) {
		connection.close();
	    }
	} catch (SQLException e) {
	     EaiLog.error("Error closing connection", e);
	}
    }
    private static Envelope handleGetContrat(Envelope envIn) throws Exception {
	Envelope envOut = new Envelope();
	Connection connexionEbankDirect = ebankdirect.getConnection();

	try {
	    List<ParamContratEpargneRMA> listParamContratEpargneRMA = HibernateDao.getParamContratEpargneRMA(connexionEbankDirect);
	    List<Contrat> contrats = getContratsFromAccounts(envIn);
	    List<Contrat> produitEpargneRMA = filterEpargneRMAContrats(contrats, listParamContratEpargneRMA);

	    enrichContratsWithEpargne(produitEpargneRMA);

	    envOut = WriteFlux.writeFluxListContrat(produitEpargneRMA);
	     EaiLog.info("Selection produit epargne terminée avec succès.");
	} catch (Exception e) {
	     EaiLog.error("Exception during contract retrieval: " + e.getMessage(), e);
	    envOut = WriteFlux.writeFluxMSG(Constante.codeErreurGetContrat, Constante.msgPrbTechnique);
	} finally {
	    closeConnection(connexionEbankDirect);
	}

	return envOut;
    }

    private static List<Contrat> getContratsFromAccounts(Envelope envIn) throws Exception {
	List<Contrat> contrats = new ArrayList<>();
	List<CompteClient> objectsMap = getCompteClientsFromEnvelope(envIn);

	for (CompteClient compteClient : objectsMap) {
	    String numCompte = compteClient.getNumcompte();
	    Envelope fluxInput = WriteFlux.writeFluxInToNumCompte(numCompte, 1, PAGE_SIZ);
	    Envelope envOutContratRMA = WriteFlux.GetFluxContratEJB(Parser.marshall(fluxInput));

	    if (!"1111".equals(envOutContratRMA.getNodeAsString("Flux/Code"))) {
		contrats.addAll(extractContratsFromEnvelope(envOutContratRMA));
	    } else {
		 EaiLog.info("ENV OUT KO: " + envOutContratRMA);
	    }
	}

	return contrats;
    }

    private static List<CompteClient> getCompteClientsFromEnvelope(Envelope envIn) throws ParsingException {
	List<CompteClient> objectsMap = new ArrayList<>();
	int accountsNumber = envIn.getNodeAsList("flux/comptes").size();

	for (int i = 1; i <= accountsNumber; i++) {
	    List<String> accountsListFromFlow = envIn.getNodeAsList("flux/comptes/compte," + i);
	    objectsMap.add(new CompteClient(accountsListFromFlow.get(0)));
	}

	return objectsMap;
    }

    private static List<Contrat> extractContratsFromEnvelope(Envelope envOutContratRMA) throws Exception {
	List<Contrat> contrats = new ArrayList<>();
	int sizeFlux = envOutContratRMA.getNodeAsList("Flux/Bancassurance").size();

	for (int p = 1; p <= sizeFlux; p++) {
	    List<String> listFromFlux = envOutContratRMA.getNodeAsList("Flux/Bancassurance/Row," + p);
	    contrats.add(new Contrat(listFromFlux.get(0), listFromFlux.get(1), listFromFlux.get(2),
		    listFromFlux.get(3), listFromFlux.get(4), listFromFlux.get(5), listFromFlux.get(6),
		    listFromFlux.get(7), listFromFlux.get(8), listFromFlux.get(9)));
	}

	return contrats;
    }

    private static List<Contrat> filterEpargneRMAContrats(List<Contrat> contrats, List<ParamContratEpargneRMA> listParamContratEpargneRMA) {
	List<Contrat> produitEpargneRMA = new ArrayList<>();

	for (Contrat contrat : contrats) {
	    for (ParamContratEpargneRMA param : listParamContratEpargneRMA) {
		if (contrat.getCodePops().equals(param.getCodeProduit())) {
		    produitEpargneRMA.add(contrat);
		    break;
		}
	    }
	}

	return produitEpargneRMA;
    }

    private static void enrichContratsWithEpargne(List<Contrat> produitEpargneRMA) throws Exception {
	for (Contrat contrat : produitEpargneRMA) {
	    // Directly assign the Double value
	    Double epargneSalarialeRevalorisee = WebServiceRMA.consulterContrat(contrat.getNumContrat())
		    .getEpargneSalarialeRevalorisee();

	    // Set the Double value to the contrat object
	    contrat.setEpargneSalarialeRevalorisee(epargneSalarialeRevalorisee);
	}
    }



    private static Envelope handleConsulterContrat(Envelope envIn) throws Exception {
	Envelope envOut = new Envelope();
	String numContrat = envIn.getNodeAsString(FLUX_CONTRAT_NUM_CONTRAT);
	String typeContrat = envIn.getNodeAsString(FLUX_CONTRAT_TYPE_CONTRAT);

	try {
	    // Get contract info
	    Contrat contrat = WebServiceRMA.consulterContrat(numContrat);
	     EaiLog.info("etat de contrat :" + contrat.getEtatContrat());

	    // Use helper class to get prestations and calculate retraits
	    List<ListPrestations> prestationList = ContratHelper.getPrestationList(numContrat);
	    double montantRetraitExceptionnels = ContratHelper.calculateTotalRetraits(prestationList);

	    // Set values on contract
	     EaiLog.info("somme mantant des retraits exceptionnels: " + montantRetraitExceptionnels);
	    contrat.setMontantRetraitExceptionnels(montantRetraitExceptionnels);
	    contrat.setLibelleProduit(typeContrat);

	    // Generate response
