    private Envelope getFakeResponseEnvelope(String service) throws ParsingException, IOException {
	InputStream inputStream = Thread.currentThread().getContextClassLoader().getResourceAsStream(service);
	StringBuilder response = new StringBuilder();
	BufferedReader br = new BufferedReader(new InputStreamReader(inputStream));

	for (String line; (line = br.readLine()) != null;) {
	    response.append(line);
	}

	return Parser.unmarshall(response.toString());
    }
