    private NotificationVoOut sendNotification(NotificationVoIn notificationVoIn) throws Exception {

        Log.debug("Preparation du resultat ");
        NotificationVoOut notificationVoOut = new NotificationVoOut();
        Gson gson = new GsonBuilder().create();
        String json = gson.toJson(notificationVoIn);
        Log.info(String.format("Notification json flux in %s", json));
        SSLContextBuilder builder = new SSLContextBuilder();
        builder.loadTrustMaterial(null, TrustAllStrategy.INSTANCE);

        SSLConnectionSocketFactory sslsf = new SSLConnectionSocketFactory(
                builder.build());


        CloseableHttpClient httpClient = HttpClients.custom().setSSLSocketFactory(
                sslsf).build();


        String baseUrl = resolverFromUDDI();


        Log.info("BASE URL   " + baseUrl);
        HttpPost httpPost = new HttpPost(baseUrl);

        Log.info("http post   " + httpPost);
        StringEntity entity = new StringEntity(json, HTTP.UTF_8);
        entity.setContentType("application/json");
        httpPost.setEntity(entity);
        HttpResponse response = httpClient.execute(httpPost);
        String responseStr = EntityUtils.toString(response.getEntity());
        Log.info(String.format("push notif response service : \ncode %d  \nresponse %s",
                response.getStatusLine().getStatusCode(), responseStr));
        PushNotifApiResponse pushNotifApiResponse = gson.fromJson(responseStr, PushNotifApiResponse.class);
        Log.info(String.format("response str %s", responseStr));

        Log.info(String.format("Push notif api response : %s", pushNotifApiResponse.toString()));

        notificationVoOut.setCodeRetour(pushNotifApiResponse.getCodeRetour());
        notificationVoOut.setMessageRetour(pushNotifApiResponse.getMsgRetour());
        if(Constants.SUCCESS_CODE.equalsIgnoreCase(notificationVoOut.getCodeRetour())){
            if(pushNotifApiResponse.getTargetUsers() != null) {
                saveNotif(notificationVoIn, notificationVoOut, pushNotifApiResponse);
            }else{
                saveNotif(notificationVoIn,notificationVoOut);
            }
            Log.info("saved success");
        }else{

            saveNotif(notificationVoIn,notificationVoOut);
        }
        return notificationVoOut;


    }




    public static String resolverFromUDDI() throws IOException {
        URL uddiEndPoint = null;
        try {
            Log.info("Calling service: dgt_ws_notificationpush");
            UddiServiceInfos uddiServiceInfos = UddiClient.findService(Constants.URL_WS);
            uddiEndPoint = new URL(uddiServiceInfos.getUrl());
            Log.info("##---->Service response => " + uddiEndPoint);
        } catch (UddiException | MalformedURLException e) {
            Log.error("Exception appel UDDI:", e);
        }

        if (uddiEndPoint == null) {
            throw new IllegalStateException("Service endpoint is not available. UDDI lookup returned null.");
        }

        return uddiEndPoint.toString();
    }

