	public Envelope process(Envelope envIn) throws Exception  {
		Log.initLogTraceInfos(envIn);
		Log.setNewThreadId();
		Log.setServiceName(envIn.getNodeAsString(FLUX_ACTION_PATH));
		Log.info("[MM]: invIn pour action "+envIn.getNodeAsString(FLUX_ACTION_PATH)+Parser.unmarshall(envIn.toString()));

		Envelope envOut = new Envelope();

		Connection connexionEbankDirect = null;
		Connection connexiondataCenterDs= null;
		Connection connexionDWHDSXA = null;

		try {
			 connexionEbankDirect = ebankdirect.getConnection();
			connexionDWHDSXA = DWHDSXA.getConnection();
			connexiondataCenterDs = dataCenterDs.getConnection();
		} catch (Exception e1) {
			// TODO Auto-generated catch block
			Log.info(" Exception Start connexiondataCenterDs "+e1.getMessage() + "  "+e1.getMessage());
			////AppLog.info(" Exception Start connexiondataCenterDs "+e1.getMessage() + "  "+e1.getMessage());
			Log.error("[MM]: Connexion to datasource failure",e1);
		}


		try {
			envOut = traitement(envIn, connexionEbankDirect, connexionDWHDSXA, connexiondataCenterDs);
			String codee = envOut.getNodeAsString("flux/code");
            Log.info("code retour  traitement Souscription Assistance " + codee);
            if (envIn.getNodeAsString(FLUX_ACTION_PATH).equals("addSouscription")) {
            	Log.info("inside process methode addSouscription");
            	//codee = "111";
            if ("111".equals(codee)) {
                Log.info("Test sctx.setRollbackOnly()");
                sctx.setRollbackOnly();
            }
            }


		} catch (Exception e) {
			Log.error("exeption Exception  traitement   ...",e);
			//AppLog.info("exeption Exception  traitement   ..."+ e.getMessage());
			sctx.setRollbackOnly();

		}

		Log.info("[MM]: flux en sortie traitement  BMCE DIRECT  pour l'action :  "+ envIn.getNodeAsString(FLUX_ACTION_PATH).toString()+ Parser.unmarshall(envOut.toString()));
//	    envOut = Parser.unmarshall(envOut.toString());
		 if(connexionEbankDirect!=null){connexionEbankDirect.close();}
		return envOut;


	}

	// traitement


	public static Envelope traitement(Envelope envIn,Connection connexionEbankDirect ,Connection connexionDWHDSXA,	Connection connexiondataCenterDs) throws  Exception   {

		 Envelope envOut = new Envelope();

		// Log.info("[MM] start traitement methode envIn: "+envIn);
		 // action à executer
		 Action action = Action.valueOf(envIn.getNodeAsString(FLUX_ACTION_PATH).toString().trim().toUpperCase());

		 Log.info("[MM] action:"+action);


	switch (action) {

		case TEST: {
		    envOut = actionTest();
		}
			break;


		case GETINFOTIER: {
		    actionGetInfoTier(envIn, envOut);
		}

		break;

		case GETNUMEROPOLICE: {
		    envOut = actionNumeroPolice(envIn, connexionEbankDirect);

		}

		break;



		case TESTSENDEMAIL: {
		   actionTestEmail(envIn);

		}

		break;



		case SENDMAIL: {

		    envOut = actionTestMail(envOut);

		}
		break;


		case VALIDATEACCOUNT: {
		    envOut = actionVAlidateAccount(envIn, connexionEbankDirect, envOut);

		}
		break;

		case GETHISTORIQUE: {

		    envOut = actionGetHistorique(envIn, connexionEbankDirect);

		}

		break;

		case GETREFERENTIELSOUSCRIPTION: {

//			ReadPropertiesFile prf = new ReadPropertiesFile();
//			prf.loadPropertiesFile();
//			Log.info("**************** userName: "+prf.getUserName());
//			Log.info("**************** userName: "+prf.getUserName());
//			Log.info("**************** Password: "+prf.getPassWord());

		    envOut = actionGetRefSouscription();

		}
		break;

		case GETVILLEBYPAYS: {
		    envOut = actionGetVilleByPays(envIn);

		}
		break;

		case ADDSOUSCRIPTION:
		    envOut = AddSouscription(envIn, connexionEbankDirect, connexionDWHDSXA, connexiondataCenterDs);
		    break;



		case GENERATEDOCUMENTS:
		    envOut = actionGenerateDocument(envIn, envOut);
		    break;

		case UPDATESOUSCRIPTION:
		    envOut = actionUpdateSouscription(envIn, connexionEbankDirect, envOut);
		    break;




		case GETDEVIS:
		    envOut = actionGetDevis(envIn, envOut);
		    break;

		default:
			break;
	}// fin switch


		//Close Ressources

		if (connexionEbankDirect != null) {
		    connexionEbankDirect.close();
		}


		if (connexiondataCenterDs != null) {
		    connexiondataCenterDs.close();
		}
		if (connexionDWHDSXA != null) {
		    connexionDWHDSXA.close();
		}


		return envOut;

	}

