    private static Envelope actionUpdateSouscription(Envelope envIn, Connection connexionEbankDirect, Envelope envOut) {
	try {

		Log.info("Begin updateSouscription function: "+ envIn.toString());
		String numContrat = envIn.getNodeAsString("flux/numContrat").toString();
		Log.info("numContrat: "+numContrat);
		String guidCg = envIn.getNodeAsString("flux/guidCp").toString();
		Log.info("guidCg: "+guidCg);
		String guidMandat = envIn.getNodeAsString("flux/guidMandat").toString();
		Log.info("guidMandat: "+guidMandat);
		String guidAttestation = envIn.getNodeAsString("flux/guidAttestation").toString();
		Log.info("guidAttestation: "+guidAttestation);
		boolean reponse = HibernateDao.updateSouscription(numContrat, guidCg,guidMandat, guidAttestation,
			connexionEbankDirect);
		if(reponse) {
			envOut = WriteFlux.writeFluxMsg("0000", "success");
		}else {
			envOut = WriteFlux.writeFluxMsg("1000", "erreur update !");
		}
	}catch(Exception ex){
	    	Log.error("Exception updateSouscription : ", ex);

	}
	return envOut;
    }

