    private static Envelope processSoldeAndSouscription(String NUM_COMPTE, String categorie, Connection connexiondataCenterDs,
	    Connection connexionDWHDSXA, Double TARIFICATION, String centredefrais, String ID_CLIENT, String codeProduit,
	    String codeAutorisation, Envelope env, Envelope envIn, String CANAL, String CONTRAT_BAD, String DATE_SOUSCRIPTION,
	    String DELEGUE, String emailSouscripteur, String TIERS, String NUM_POLICE, String NUM_CONTRAT,
	    String NUM_AUTORISATION, Connection connexionEbankDirect, String fonctionnaire, String codeTypeDuree,
	    String codeDuree, String dateEffet, String nom, String prenom, String codeTypePieceIdentite, String numPiece,
	    String codeCivilite, String dateNaissance, String lieuNaissance, String adresse, String codeProfession,
	    String codeNationalite, String codePostale, String codeSituationFamiliale, String email, String telephone1,
	    String telephone2, String codeVille, String nomVilleAssure, String codePays, String nomPaysAssure,
	    String beneficiaireCapitalDeces, int autreContrat, String nomSouscripteur, String prenomSouscripteur,
	    String codeTypePieceIdentiteSouscripteur, String numPieceSouscripteur, String codeCiviliteSouscripteur,
	    String dateNaissanceSouscripteur, String lieuNaissanceSouscripteur, String adresseSouscripteur,
	    String codeProfessionSouscripteur, String codeNationaliteSouscripteur, String codePostaleSouscripteur,
	    String codeSituationFamilialeSouscripteur, String telephone1Souscripteur, String telephone2Souscripteur,
	    String codeVilleSouscripteur, String nomVilleSouscripteur, String codePaysSouscripteur,
	    String nomPaysSouscripteur, String numCompteBancaireSouscripteur, String isSouscripteurMoralSouscripteur,
	    double primeNetteTTC, double taxesParaFiscale, double primeNetteHT, double taxes, double commission,
	    int nbrVehicule, int nbConjoints, int nbrAscendant, int nbrEnfants, int nbrTiercePersonne)throws Exception  {

	objetRetourSolde retourSolde = new objetRetourSolde();
	Envelope envOut;
	retourSolde = HibernateDao.getSolde(NUM_COMPTE, categorie, connexiondataCenterDs, connexionDWHDSXA);
	Log.info("Le retour de l'objet solde: " + retourSolde);
	String codeError = retourSolde.getCodeRetour();

	if (!codeError.equals("1000")) {
	    Log.info("problème technique retourSolde " + retourSolde.getCodeRetour() + " " + retourSolde.getMsgRetour());
	    return WriteFlux.writeFluxMsg(retourSolde.getCodeRetour(), Constante.msgPrbTechnique);
	}

	Long soldeInt = Long.parseLong(retourSolde.getSolde());
	Log.info("Le solde Int: " + soldeInt);

	int montantDTV = (int) (TARIFICATION * 100);
	String montantBlocageSolde = String.valueOf(montantDTV * 10);
	Log.info("montant à bloquer est " + montantBlocageSolde + " soldeInt / 1000: " + soldeInt / 1000);

	handleSaisieDArretEtBlockage(retourSolde);
	handleSaisieDArret(retourSolde);
	handleBlockage(retourSolde);

	if (TARIFICATION > soldeInt / 1000) {
	    Log.info("solde insuffisant ");
	    return WriteFlux.writeFluxMsg("111", "votre solde est insuffisant pour faire cette opération");
	}

	String dateSysteme = getDateSysteme();
	String codeAutorisationPourBlocage = getCodeAutorisationPourBlocage(NUM_COMPTE, retourSolde, codeAutorisation);
	String libelle = "Paiement Souscription RMA Assistance produit : " + codeProduit;
	Log.info(libelle);

	String retourBlocageSolde = HibernateDao.blocageSolde(centredefrais, retourSolde.getCodePops(), retourSolde.getCptGen(),
		NUM_COMPTE, montantBlocageSolde, libelle, ID_CLIENT, codeAutorisationPourBlocage, dateSysteme);

	if (!retourBlocageSolde.equals("1000")) {
	    Log.info("problème technique retour blocage Solde " + retourBlocageSolde);
	    return WriteFlux.writeFluxMsg(retourBlocageSolde, Constante.msgPrbTechnique);
	}

	// Process subscription
	Souscription souscription = getSouscription(codeProduit, fonctionnaire, codeTypeDuree, codeDuree, dateEffet,
		nom, prenom, codeTypePieceIdentite, numPiece, codeCivilite, dateNaissance, lieuNaissance, adresse,
		codeProfession, codeNationalite, codePostale, codeSituationFamiliale, email, telephone1, telephone2,
		codeVille, nomVilleAssure, codePays, nomPaysAssure, beneficiaireCapitalDeces, autreContrat,
		codeAutorisationPourBlocage, nomSouscripteur, prenomSouscripteur, codeTypePieceIdentiteSouscripteur,
		numPieceSouscripteur, codeCiviliteSouscripteur, dateNaissanceSouscripteur, lieuNaissanceSouscripteur,
		adresseSouscripteur, codeProfessionSouscripteur, codeNationaliteSouscripteur, codePostaleSouscripteur,
		codeSituationFamilialeSouscripteur, emailSouscripteur, telephone1Souscripteur, telephone2Souscripteur,
		codeVilleSouscripteur, nomVilleSouscripteur, codePaysSouscripteur, nomPaysSouscripteur,
		numCompteBancaireSouscripteur, isSouscripteurMoralSouscripteur);

	extractedVehicule(envIn, nbrVehicule, nomSouscripteur, prenomSouscripteur, numPieceSouscripteur,
		dateNaissanceSouscripteur, souscription);
	extractedListeConjoints(envIn, nbConjoints, souscription);
	extractedListeAscendent(envIn, nbrAscendant, souscription);
	extractedAscendant(envIn, nbrAscendant, souscription);
	extractedEnf(envIn, nbrEnfants, souscription);

	List<MemeToit> listMemeToit = getMemeToits(envIn, nbrTiercePersonne);
	Log.info("fin de liste Meme Toit");
	souscription.setLstMemeToit(listMemeToit);
	souscription.setPrimeAnnuelleTTC(TARIFICATION);
	souscription.setPrimeNetteTTC(primeNetteTTC);
	souscription.setTaxesParaFiscale(taxesParaFiscale);
	souscription.setPrimeNetteHT(primeNetteHT);
	souscription.setTaxes(taxes);
	souscription.setCommission(commission);

	String token = HibernateDao.getToken();
	Log.info("Before calling the service generer contrat");
	souscription = (Souscription)HibernateDao.getResponse(souscription, "api/genererContrat", souscription, token, "POST");
	Log.info(RETOUR_DE_SERVICE_GENERERCONTAT + souscription.toEnv());

	NumeroPolice(souscription);
	env.setBody(FLUX1 + souscription.toEnv() + FLUX);
	Parser.update(env);
	envOut = env;

//	  NUM_POLICE = envOut.getNodeAsString("flux/Souscription/idPolice");
//	Log.info("NUM_POLICE:" + NUM_POLICE);
	String resultPolicy = envOut.getNodeAsString("flux/Souscription/idPolice");
	String numPoliceValue = resultPolicy; // Create a local variable

	Log.info("Extracted numPoliceValue: " + numPoliceValue);

	// Only update NUM_POLICE if necessary
	if (numPoliceValue != null && !numPoliceValue.isEmpty()) {
	    NUM_POLICE = numPoliceValue;
	    Log.info("NUM_POLICE updated to: " + NUM_POLICE);
	} else {
	    Log.warn("numPoliceValue is null or empty, NUM_POLICE remains unchanged.");
	}



	handleSouscriptionPersistence(connexionEbankDirect, envOut, CANAL, codeProduit, CONTRAT_BAD, DATE_SOUSCRIPTION,
		DELEGUE, emailSouscripteur, ID_CLIENT, TIERS, nbrAscendant, nbConjoints, nbrEnfants, nbrTiercePersonne,
		nbrVehicule, NUM_COMPTE, telephone1, NUM_POLICE, NUM_CONTRAT, TARIFICATION, NUM_AUTORISATION,
		codeAutorisationPourBlocage);

	Log.info("[MM]: after display subscription");
	return envOut;
    }



