	    sRma.setTEL(telephone1);
	    sRma.setNUM_POLICE(NUM_POLICE);
	    sRma.setNUM_CONTRAT(NUM_CONTRAT);
	    sRma.setTARIFICATION(TARIFICATION);
	    sRma.setNUM_AUTORISATION(NUM_AUTORISATION);
	    sRma.setREF_BLOCAGE(codeAutorisationPourBlocage);

