    private static String getCodeAutorisationPourBlocage(String NUM_COMPTE, objetRetourSolde retourSolde, String codeAutorisation) {
	String codeAutorisationPourBlocage = NUM_COMPTE.substring(3, 6) + NUM_COMPTE.substring(10, 12) //Centre de frais sur 5
		    + NUM_COMPTE.substring(17, 22) //racine sur 5
		    + NUM_COMPTE.substring(15, 17) //annex sur 2
		    + NUM_COMPTE.substring(12, 15) // categorie sur 3
	    + NUM_COMPTE.substring(8, 10)  //devise sur 2
	    + retourSolde.getCptGen() //compte general sur 5
	    + "A0" //sur 5 //Sur 2 suite a la demande de la banque pour le leve de blocage
	    + StringHelper.padLeft(codeAutorisation, 9,'0');//sequence sur 9

	Log.info("code Autorisation Pour Blocage  Solde pour le compte  "+ NUM_COMPTE +" et "+ codeAutorisationPourBlocage);
	return codeAutorisationPourBlocage;
    }

