@Transactional(propagation = Propagation.NOT_SUPPORTED)
public class CheckSoldUC implements BaseUseCase {

    @Autowired
    CheckSoldeService checkSoldeService;

    @Override
    public ValueObject execute(ValueObject voIn) throws FwkRollbackException {

	EaiLog.info("=== Starting CheckSoldUC Process ===");

	LocalDateTime startDate = LocalDateTime.now();
	CheckSoldIn checkSoldIn = (CheckSoldIn) voIn;
	CheckSoldOut checkSoldOut = new CheckSoldOut();

	EaiLog.info("Step 1: Analyzing input parameters");
	EaiLog.info("Input Account: " + (checkSoldIn.getAccount() != null ? checkSoldIn.getAccount() : "NULL"));
	EaiLog.info("Input Amount: " + (checkSoldIn.getAmount() != null ? checkSoldIn.getAmount() : "NULL"));
	if (checkSoldIn.getAccount() == null) {
	    EaiLog.warn("WARNING: Account parameter is NULL");
	}
	if (checkSoldIn.getAmount() == null) {
	    EaiLog.warn("WARNING: Amount parameter is NULL");
	}
	EaiLog.info("Step 2: Validating VadCarteParamsService dependency");

	try {
	    EaiLog.info("Step 3: Executing sold check service");
	    EaiLog.info("Calling vadCarteParamsService.checkSold() with account: " + checkSoldIn.getAccount() + ", amount: " + checkSoldIn.getAmount());


	    SoldData soldData = checkSoldeService.checkSold(checkSoldIn.getAccount(), checkSoldIn.getAmount());
	    String soldMsg = soldData.getMsgRetour();
	    EaiLog.info("Step 4: Processing service response");
	    EaiLog.info("VadCarteParamsService returned message: " + (soldMsg != null ? soldMsg : "NULL"));
	    if (soldMsg == null) {
		EaiLog.error("ERROR: Service returned NULL message");
		checkSoldOut.setCodeRetour(Constants.ERROR_CODE);
		checkSoldOut.setMessageRetour(Wording.TECHNICAL_PROBLEM);
	    }
	    else if (soldMsg.equals(Constants.SOLD_IS_OK)) {
		EaiLog.info("SUCCESS: Sold check passed - sufficient balance available");
		EaiLog.info("Setting success response code: " + Constants.SUCCESS_CODE);
		checkSoldOut.setCodeRetour(Constants.SUCCESS_CODE);
		checkSoldOut.setMessageRetour(soldMsg);
	    } else {
		EaiLog.info("INSUFFICIENT_FUNDS: Sold check failed - insufficient balance");
		EaiLog.info("Setting error response code: " + Constants.ERROR_CODE);
		EaiLog.info("Error message from service: " + soldMsg);
		checkSoldOut.setCodeRetour(Constants.ERROR_CODE);
		checkSoldOut.setMessageRetour(soldMsg);
	    }
	} catch (AccountException e) {
	    EaiLog.error("Step 4: AccountException caught during sold check");
	    EaiLog.error("Exception type: " + e.getClass().getSimpleName());
	    EaiLog.error("Exception message: " + e.getMessage());
	    EaiLog.error("Full exception details: ", e);
	    checkSoldOut.setCodeRetour(Constants.ERROR_CODE);
	    checkSoldOut.setMessageRetour(Wording.TECHNICAL_PROBLEM);
	}

	EaiLog.info("Step 5: Building final response");
	EaiLog.info("Final response code: " + checkSoldOut.getCodeRetour());
	EaiLog.info("Final response message: " + (checkSoldOut.getMessageRetour() != null ? checkSoldOut.getMessageRetour() : "NULL"));

	EaiLog.info("=== End CheckSoldUC Process ===");
	LocalDateTime endDate = LocalDateTime.now();

	long diff = ChronoUnit.SECONDS.between(startDate, endDate);
	EaiLog.info("Execution time CheckSoldUC(in seconds) : " + diff);

	return checkSoldOut;
    }

}

