	}
    }


    private void verifyAmountForOPF(SouscriptionOpvLine line, Opv opv) {
	if (opv != null && opv.getTypeSous().contains("OPF")) {
	    try {
		int nbrTitres = Integer.parseInt(line.getNbrTitredem());
		BigDecimal cours = new BigDecimal(opv.getCours().replace(",", "."));
		BigDecimal montantLigne = new BigDecimal(line.getMntsousc().replace(",", "."));

		BigDecimal expected = cours.multiply(BigDecimal.valueOf(nbrTitres));
		BigDecimal tolerance = new BigDecimal("0.01");
               // calculer la différence entre le montant attendu et le montant réél
		if (expected.subtract(montantLigne).abs().compareTo(tolerance) > 0) {
		    throw new IllegalArgumentException(
			    "Le montant souscrit pour la ligne " + line.getNom() +
				    " doit être égal à NbrTitres * Cours : " + expected.toPlainString() +
				    " mais reçu " + montantLigne.toPlainString()
		    );
		}
	    } catch (NumberFormatException e) {
		throw new IllegalArgumentException(
			"Erreur de format numérique pour nbrTitres, cours ou montant dans la ligne " + line.getNom(),
			e
		);
	    }
	}
    }

    private void checkPositiveAmount(String value, String fieldName) {
	if (value == null || value.trim().isEmpty()) {
	    throw new IllegalArgumentException(Wording.CHAMPS+" "+fieldName+" "+"est obligatoire.");
	}

	try {
	    double amount = Double.parseDouble(value.replace(",", "."));
	    if (amount == 0) {
		throw new IllegalArgumentException(Wording.CHAMPS+" "+fieldName+" "+"ne doit PAS être égal à 0.");
	    }
	} catch (NumberFormatException e) {
	    throw new IllegalArgumentException(Wording.CHAMPS+" "+fieldName+" "+"doit être numérique.");
	}
    }

