	EaiLog.info(" Souscription rejetée : ID " + souscription.getId() + ", motif: " + motif);
	return voOut;
    }

    // Méthode pour valider une souscription
    private ValidationDemandeSouscOpvOut validateSouscription(SouscriptionOpv souscription, String motif,
	    ValidationDemandeSouscOpvOut voOut, LocalDateTime date)
	    throws ParsingException {


	SouscriptionOpv managed =
		souscriptionOPVService.FindOpvById(souscription.getId());
	managed.setStatus("VALIDE");
	managed.setMotifTraitementOpv(motif);
	managed.setDateTraitement(date.format(FORMATTER));
	//souscription.setRefBlocageCompte(codeAutorisationPourBlocage);
	souscriptionOPVService.updateSouscription(managed);

	voOut.setCodeRetour("0000");
	voOut.setMessageRetour("Demande Souscription Opv traitée avec succès.");
	EaiLog.info("Souscription validée : ID " + souscription.getId());
	return voOut;
    }
