import ma.eai.web.vo.ListCardsVoIn;
import ma.eai.web.vo.ListCardsVoOut;


/**
 * Implementation du UseCase
 * @author ingdev
 *
 */
@UseCase
public class ListCardsUC implements BaseUseCase {

    @Autowired
    ICardsService cardsService;
    @Autowired
    IBadEbankingService badEbankingService;
    @Autowired
    IJwtService jwtService;
    @Override
    public ValueObject execute(ValueObject voIn) {
	EaiLog.info("===== Debut UseCase ListCardsUC =====");

	LocalDateTime startDate = LocalDateTime.now();
	EaiLog.info("Start timestamp: " + startDate);

	ListCardsVoIn in = (ListCardsVoIn) voIn;
	EaiLog.info("Incoming VO: idConnection=" + in.getIdConnection()
		+ ", listAccounts=" + in.getListAccounts());

	ListCardsVoOut out = new ListCardsVoOut();

	try {
	    // 1) BadEbanking lookup
	    String idConn = in.getIdConnection();
	    if (idConn != null && !idConn.isEmpty()) {
		EaiLog.info("Looking up BadEbanking for connectionId=" + idConn);
		BadEbanking bad = badEbankingService.getBadEbankingByConnetionId(idConn);
		if (bad != null) {
		    EaiLog.info("  → Found BadEbanking: idConnexion=" + bad.getIdConnexion()
			    + ", numTiers=" + bad.getNumTiers());
		    List<String> overrideAccounts = L0004.getComptesFromTiers(bad.getNumTiers());
		    EaiLog.info("  → Overriding accounts with L0004: " + overrideAccounts);
		    in.setListAccounts(overrideAccounts);
		} else {
		    EaiLog.info("  → No BadEbanking entry for this connection");
		}
	    }

	    EaiLog.info("Final listAccounts=" + in.getListAccounts());

	    // 2) Tokenisation health
	    boolean tokenUp = cardsService.isTokenisationUP();
	    EaiLog.info("cardsService.isTokenisationUP() → " + tokenUp);
	    out.setAddToWalletActive(tokenUp);

	    if (tokenUp) {
		// 3) Call eligibility service
		EaiLog.info("Calling getListEligibleCardsRich(...) with "
			+ in.getListAccounts().size() + " accounts");
		List<Card> cards = cardsService.getListEligibleCardsRich(in.getListAccounts());
		EaiLog.info("  ← Returned " + cards.size() + " eligible cards");
		out.setListCard(cards);

		out.setCodeRetour(Constants.SUCCESS_CODE);
		out.setMessageRetour("OK");
	    } else {
		EaiLog.warn("Tokenisation is DOWN");
		out.setCodeRetour(Constants.ERROR_CODE);
		out.setMessageRetour("Tokenisation is DOWN");
	    }

	} catch (HttpException e) {
	    EaiLog.error("HttpException in ListCardsUC", e);
	    out.setCodeRetour(e.getCodeError());
	    out.setMessageRetour(e.getMessageError());

	} catch (Exception e) {
	    EaiLog.error("Unexpected exception in ListCardsUC", e);
	    out.setCodeRetour(Constants.ERROR_CODE);
	    out.setMessageRetour(Constants.ERROR_MSG);
	}

	LocalDateTime endDate = LocalDateTime.now();
	long seconds = ChronoUnit.SECONDS.between(startDate, endDate);
	EaiLog.info("Fin UseCase ListCardsUC, duration=" + seconds + "s");
	EaiLog.info("===== Sortie VO: codeRetour=" + out.getCodeRetour()
		+ ", messageRetour=" + out.getMessageRetour()
		+ ", listCard=" + (out.getListCard() != null ? out.getListCard().size() : 0)
		+ " =====");

	return out;
    }


}
