                EaiLog.info("flux en sortie traitement VRT  flux out:  " + Parser.unmarshall(envOut.toString()));
                envOut = Parser.unmarshall(Parser.unmarshall(envOut.toString()).toString());
                String msg = envOut.getNodeAsString("flux/message");

                EaiLog.info("code retour  traitement VRT " + msg);

                if (msg == null || !msg.equals("OK")) {
                    EaiLog.info("sctx.setRollbackOnly() pour VRT ");
                    sctx.setRollbackOnly();

                }
                EaiLog.info("ici");
            }

        } catch (Exception e) {
            EaiLog.error("exeption Exception  Traitement VRT  ..." + e.getMessage());
            sctx.setRollbackOnly();
        } catch (Throwable e1) {
            EaiLog.error("exeption Throwable Traitement VRT " + e1.getMessage());
            sctx.setRollbackOnly();
        }
        EaiLog.info("fin traitement VRT");
        return envOut;
    }

    public static Envelope Traitement(Envelope envIn, Connection connexionEbankDirect,
                                      Connection connexionEbankInterface, Connection connexionDWHDSXA, Connection connexiondataCenterDs)
            throws Throwable {
        String[] ord = envIn.getNodeAsString(Constante.FLUX_ORDONNATEUR_PATH).split("_");

        String idOrd = ord[0] + "_" + ord[1];
        Envelope envOut = new Envelope();
        // action à executer
        Action action = Action.valueOf(envIn.getNodeAsString(Constante.FLUX_ACTION).trim().toUpperCase());
        switch (action) {
            case CONTROLPLAFONDMONTANT: {
                envOut = controlPlafondMontant(envIn, connexionEbankDirect);
            }
            break;
            case GETBENIFICIAIRES:
                EaiLog.info("test  entréé service java 12/03/2018");
                envOut = getbenificiaires(envOut, idOrd);
                break;
            case DETAIHISTORIQUE:
                envOut = detaiHistorique(envOut, envIn);
                break;
            case MODIFBENIF:
                envOut = modifBenif(envOut, envIn);
                break;

            case SAVEBENIF:
                envOut = saveBenif(envOut, envIn, action);
                break;
            case SUPPRIMER:
                envOut = supprimer(envOut, envIn, action);
                EaiLog.info(Constante.END_ACTION_PATH + action);
                break;
            case TESTRIB:
                envOut = testRibReferentielCompte(envOut, envIn);
                break;
            case EXEVRT_TST: {
                envOut = exeVrtTst(envIn, action);
            }
            break;
            case EXEVRT:
                String msg = "NOK";
                MsgVirement retour = new MsgVirement("", null);
                try {
                    retour = new MsgVirement("", null);
                    msg = "NOK";
                    String etat = "";

                    String numCompteBeneficiare = envIn.getNodeAsString(Constante.FLUX_NUMCOMPTE_PATH).toString();
                    //bloquer les virements vers ces deux numros de compte  CNSS  et TGR
                    if (Arrays.asList("011780000063210006013657", "001810007825150110695546").contains(numCompteBeneficiare)) {
                        etat = "0099";
                        EaiLog.info("Ce virement n'est pas autorisé,le compte bénificiare est bloqué.");
                        envOut = WriteFlux.writeMSGString(Constante.codeErreurPbTechnique,
                                "Ce virement n'est pas autorisé, le compte bénificiare est bloqué.", etat);
                        break;
                    }

                    String tier = envIn.getNodeAsString("flux/tier").toString();
                    EaiLog.info("tier: " + tier);
                    String idClient = envIn.getNodeAsString(Constante.FLUX_ID_CLIENT_PATH).toString();
                    EaiLog.info("idClient: " + idClient);
                    String numDLG = envIn.getNodeAsString("flux/numDLG").toString();
                    EaiLog.info("numDLG: " + numDLG);
                    String ctrBAD = envIn.getNodeAsString("flux/ctrBAD").toString();
                    EaiLog.info("ctrBAD: " + ctrBAD);
                    String canal = envIn.getNodeAsString("flux/canal").toString();
                    EaiLog.info("canal: " + canal);
                    String flagAction = envIn.getNodeAsString("flux/flagAction").toString();
                    EaiLog.info("flagAction: " + flagAction);

                    String numcomptedebit = envIn.getNodeAsString(Constante.FLUX_NUMCOMPTEDEBIT_PATH).toString();
                    EaiLog.info("numcomptedebit: " + numcomptedebit);

                    String montantSaisi = envIn.getNodeAsString(Constante.FLUX_MONTANT_PATH).toString();
                    EaiLog.info("montantSaisi: " + montantSaisi);
                    // double montantDouble=Double.parseDouble(montantSaisi.replace(',', '.'));
                    double montantDouble = Double.parseDouble(montantSaisi.replace(",", ".").replace(" ", ""));
                    int montantDTV = (int) (montantDouble * 100);
                    String montantDtvString = String.valueOf(montantDTV);
                    EaiLog.info("montant vrt perm à envoyer  DTV " + montantDTV);

                    String categorie = numcomptedebit.substring(12, 15);

                    String idBenef = envIn.getNodeAsString(Constante.FLUX_IDBENIF_PATH);
                    String refNext = envIn.getNodeAsString(Constante.FLUX_ID_VRT_PATH);
                    // controle solde
                    objetRetourSolde retourSolde = new objetRetourSolde();
                    retourSolde = HibernateDao.getSolde(numcomptedebit, categorie, connexiondataCenterDs, connexionDWHDSXA);
                    EaiLog.info("retourSolde :" + retourSolde); // unités poste

                    // controle compte : saisie d'arret et blockage
                    if (isCompteBloqueEtSaisieArret(retourSolde)) {
                        etat = "0020";
                        EaiLog.info("Votre compte est bloqué et en saisie d’arrêt .");
                        envOut = WriteFlux.writeFluxMSG(Constante.codeErreurPbTechnique,
                                "Votre compte est bloqué et en saisie d’arrêt .", etat, refNext, idBenef);
                        break;
                    }

                    // controle compte : saisie d'arret
                    if (!retourSolde.getSaisieArret().equals("0")) {
                        etat = "0018";
                        EaiLog.info("Votre compte est en saisie d’arrêt .");
                        envOut = WriteFlux.writeFluxMSG(Constante.codeErreurPbTechnique,
                                "Votre compte est en saisie d’arrêt .", etat, refNext, idBenef);
                        break;
                    }
                    // controle compte : blockage
                    if (!retourSolde.getBlcCompte().equals("0")) {
                        etat = "0019";
                        EaiLog.info("Votre compte est bloqué .");
                        envOut = WriteFlux.writeFluxMSG(Constante.codeErreurPbTechnique, "Votre compte est bloqué .", etat,
                                refNext, idBenef);
                        break;
                    }

                    VirementVO fluxvo = new VirementVO(envIn.getNodeAsString(Constante.FLUX_ORDONNATEUR_PATH),
                            envIn.getNodeAsString(Constante.FLUX_ID_VRT_PATH), envIn.getNodeAsString(Constante.FLUX_NOM_PATH),
                            envIn.getNodeAsString(Constante.FLUX_MOTIF_PATH), envIn.getNodeAsString(Constante.FLUX_MAX_PATH),
                            envIn.getNodeAsString(Constante.FLUX_MIN_PATH), envIn.getNodeAsString(Constante.FLUX_NUMCOMPTE_PATH),
                            // envIn.getNodeAsString(Constante.FLUX_MONTANT_PATH),
                            montantDtvString, envIn.getNodeAsString(Constante.FLUX_INTITULE_PATH),
                            envIn.getNodeAsString(Constante.FLUX_NUMCOMPTEDEBIT_PATH), envIn.getNodeAsString(Constante.FLUX_NOMDEBIT_PATH),
                            envIn.getNodeAsString(Constante.FLUX_TYPE_PATH), envIn.getNodeAsString(Constante.FLUX_IDBENIF_PATH),
                            envIn.getNodeAsString(Constante.FLUX_SAVE_PATH), envIn.getNodeAsString(Constante.FLUX_JOUREXE_PATH),
                            envIn.getNodeAsString(Constante.FLUX_PERIODE_PATH), envIn.getNodeAsString(Constante.FLUX_DATE_FIN_PATH),
                            envIn.getNodeAsString(Constante.FLUX_PERIODELIBELL_PATH), envIn.getNodeAsString(Constante.FLUX_NOMORD_PATH),
                            envIn.getNodeAsString(Constante.FLUX_EMAIL_PATH));

                    // //--------------------- debut Appel
                    // DTV-------------------------------
                    SimpleDateFormat formatter = new SimpleDateFormat(Constante.DATE_FORMAT);
                    Date currentTime_1 = new Date();
                    String dateString = formatter.format(currentTime_1);
                    String dateProchExecution =
                            fluxvo.getJourexe().substring(0, 4) + "-" + fluxvo.getJourexe().substring(4, 6) + "-"
                                    + fluxvo.getJourexe().substring(6, 8);
                    String dateFinValidite = extractAnneeDateFin(fluxvo.getDatefin());
                    String flag = getFlagBasedOnDate(fluxvo.getJourexe(), dateString);

                    SimpleDateFormat formatter2 = new SimpleDateFormat("yyyy-MM-dd");
                    String dateString2 = formatter2.format(currentTime_1);
                    String FluxDebit =
                            "<flux><entete><fonction>0010</fonction></entete><objet><VirementPerm>" + (fluxvo.getIdVrt()
                                    .trim().equals("") ? "" : "<idVirementPerm>" + fluxvo.getIdVrt() + "</idVirementPerm>")
                                    + "<ribOrdonnateur>" + fluxvo.getNumcomptedebit() + "</ribOrdonnateur>" + "<montant>"
                                    + fluxvo.getMontant() + "</montant><libReleve>" + truncate(fluxvo.getIntitule(), 25)
                                    + "</libReleve><TPeriodicite><codePeriod>" + fluxvo.getPeriode()
                                    + "</codePeriod><libellePeriod>" + fluxvo.getPeriodelibell()
                                    + "</libellePeriod></TPeriodicite><dateProchExecution>" + dateProchExecution
                                    + "</dateProchExecution><dateFinValidite>" + dateFinValidite
                                    + "</dateFinValidite><nomOrdonnateur>" + fluxvo.getNomOrd()
                                    + "</nomOrdonnateur><transfereOrdon>0</transfereOrdon>" + "<ribBeneficiaire>"
                                    + fluxvo.getNumcompte() + "</ribBeneficiaire>" + "<nomBeneficiare>" + fluxvo.getNom()
                                    + "</nomBeneficiare><simtLibDest1 >" + fluxvo.getIntitule()
                                    + "</simtLibDest1><simtLibDest2/><simtLibDest3/><simtLibDest4/><simtLibDest5/><simtLibDest6/>"
                                    + "<natureOperation>Ebank Direct</natureOperation>"
                                    + "<transfereBenef>0</transfereBenef><dateCreation>" + dateString2
                                    + "</dateCreation><centreFraisAgence>" + fluxvo.getNumcomptedebit().substring(3, 6)
                                    + fluxvo.getNumcomptedebit().substring(10, 12)
                                    + "</centreFraisAgence></VirementPerm><VrtExecMemeJour>" + flag
                                    + "</VrtExecMemeJour><utilisateur>EBANKING</utilisateur></objet></flux>";

                    EaiLog.info(
                            "---------------------------------------------debut EJB posteAgenceVirement----------------------------------------");
                    EaiLog.info("-------------------------FLUX IN : " + FluxDebit);

                    SynchroneService posteAgenceVrt = null;

                    posteAgenceVrt = Services.find("PosteAgenceVirement", SynchroneService.class);

                    EaiLog.info("------------------------- end find :  posteAgenceVirement");

                    envIn = new Envelope();
                    envIn.setBody(FluxDebit);
                    Envelope reponseDebit = posteAgenceVrt.process(envIn);

                    // //--------------------- fin Appel
                    // DTV-------------------------------

                    EaiLog.info("######## envIn : " + reponseDebit);

                    EaiLog.info("------------------------- end process :  posteAgenceVirement");
                    EaiLog.info("------------------------- FLUX OUT :  " + ((reponseDebit == null)
                            ? "NUUUUUUUUUUUUL"
                            : reponseDebit.toString()));
                    ExeVrtHelperObj exeVrtHelperObj = handleExeVrt(reponseDebit,
                            retour, fluxvo, msg, envIn, flagAction, tier, ctrBAD, numDLG, canal);
                    msg = exeVrtHelperObj.getMsg();
                    retour = exeVrtHelperObj.getRetour();
                } catch (Exception e) {
                    EaiLog.error("erreur Setting transaction   " + e);
