    public static CheckPlafondObj checkPlafond(String retourCalculPlafond, String msg, String code) {
        if (retourCalculPlafond.equals("001")) {
            msg = "Vous avez dépassé la limite autorisée par jour: Un ou plusieurs virements permanents sont planifiés pour le même jour";
            code = "002";
        } else {

            if (retourCalculPlafond.equals("002")) {
                msg = "Vous avez dépassé la limite autorisée par mois: Un ou plusieurs virements permanents sont planifiés pour le même mois";
                code = "003";
            }

        }
        CheckPlafondObj checkPlafondObj = new CheckPlafondObj();
        checkPlafondObj.setCode(code);
        checkPlafondObj.setMsg(msg);
        return checkPlafondObj;
    }

    public static Envelope controlPlafondMontant(Envelope envIn, Connection connexionEbankDirect) throws Throwable {
        String montantOperaion = envIn.getNodeAsString("flux/montantOperation").toString();
        String idClient = envIn.getNodeAsString(Constante.FLUX_ID_CLIENT_PATH).toString();
        String periodiciteNouvVrt = envIn.getNodeAsString("flux/periodiciteNouvVrt").toString();
        String marche = envIn.getNodeAsString("flux/marche").toString();
        EaiLog.info("marche:  " + marche);

        String dateOperation = envIn.getNodeAsString("flux/dateOperation").toString();

        EaiLog.info("idClient:  " + idClient);

        String dateExpiration = envIn.getNodeAsString(Constante.FLUX_DATE_FIN_PATH).toString();
        EaiLog.info("datefin:  " + dateExpiration);
        Date dateJ = new Date();
        SimpleDateFormat dt = new SimpleDateFormat(Constante.DATE_FORMAT);
        String dateJour = dt.format(dateJ);
        EaiLog.info(" dateJour " + dateJour);

        VrtPermPlafondMontant plafondMontant = HibernateDao.controlPlafondMontant(marche, connexionEbankDirect);
        double montantOperationDouble = Double.parseDouble(montantOperaion);
        double montantMinOperation = Double.parseDouble(plafondMontant.getMin());
        double montantMaxOperation = Double.parseDouble(plafondMontant.getMax());

        // vérifier le min et le max de l'opération
        String msg = "ok", code = "000";

        String montantMin = plafondMontant.getMin();
        String montantMax = plafondMontant.getMax();
        if (montantOperationDouble < montantMinOperation || montantOperationDouble > montantMaxOperation) {
            NumberFormat formatter = NumberFormat.getInstance();

            msg = "Veuillez saisir un montant supérieur à " + formatter.format(Double.parseDouble(montantMin))
                    .replace(',', ' ') + " MAD  et inférieur à " + formatter.format(Double.parseDouble(montantMax))
                    .replace(',', ' ') + " MAD";
            code = "001";
        } else {

            // liste ancien vrt
            ArrayList<VpermVrtpermanent> listeAncienVrtPerm = new ArrayList<VpermVrtpermanent>();
            listeAncienVrtPerm = HibernateDao.getListAncienVirtPerm(connexionEbankDirect, idClient, dateJour);
            // ajout nouv vrt a la liste des ancien
            VpermVrtpermanent vpermVrtpermanent = new VpermVrtpermanent();
            vpermVrtpermanent.setJourExe(dateOperation);
            vpermVrtpermanent.setMontant(montantOperaion);
            vpermVrtpermanent.setType(periodiciteNouvVrt);
            listeAncienVrtPerm.add(vpermVrtpermanent);

            Date dateFinNouvVirement = DateUtil.getDate(Constante.DATE_FORMAT, dateExpiration);

            String retourCalculPlafond = HibernateDao.getCalculPlafond(listeAncienVrtPerm, montantOperationDouble,
                    plafondMontant, dateJ, dateOperation, dateFinNouvVirement);
            CheckPlafondObj checkPlafondObj = checkPlafond(retourCalculPlafond, msg, code);
            msg = checkPlafondObj.getMsg();
            code = checkPlafondObj.getCode();

        } // fin else

        Envelope envOut = WriteFlux.writeFluxPlafondMontant(plafondMontant, msg, montantMin, montantMax, code);
        // envOut =
        // WriteFlux.writeFluxPlafondMontant(plafondMontant,msg,code);
        EaiLog.info(Constante.FLUX_OUT_MESSAGE + Parser.unmarshall(envOut.toString()));
        EaiLog.info(Parser.unmarshall(envOut.toString()).toString());

        return envOut;
    }

