    public static void checkEmailSendNotif(String email, VirementVO fluxvo, String tier, String ctrBAD,
                                           String numDLG, String canal, String idVirementPerm) throws IOException, ParseException, SQLException {
        if (email != null && !email.isEmpty()) {
            // send mail notification begin :

            // remote notif html content file template
            // Utility.InitConstante();
            // String content = Constante.contentFilePath;

            String filePath = "maquetteNotificationVirementPermanant.html";
            String content = Utility.fileReader(filePath);

            String numero_de_compte_debite = fluxvo.getNumcomptedebit();
            String numero_de_compte_benef = fluxvo.getNumcompte();

            DecimalFormatSymbols symbols = DecimalFormatSymbols.getInstance();
            symbols.setGroupingSeparator(' ');
            symbols.setDecimalSeparator(',');
            // format double
            DecimalFormat decimalFormat = new DecimalFormat("###,###.##", symbols);
            decimalFormat.setMinimumFractionDigits(2);
            double mt = Double.parseDouble(fluxvo.getMontant()) / 100;
            String Montant_virement = decimalFormat.format(mt);

            String Nom_bénéficiaire = fluxvo.getNom();
            String Libelle_operation = truncate(fluxvo.getIntitule(), 25);
            String Date_execution_virement =
                    fluxvo.getJourexe().substring(6, 8) + "-" + fluxvo.getJourexe().substring(4, 6)
                            + "-" + fluxvo.getJourexe().substring(0, 4);
            String Etat_virement = "En cours";
            String Date_de_fin_du_virement_permanent = Utility.formatDate2String(
                    Utility.stringToDate(fluxvo.getDatefin(), Constante.DATE_FORMAT), Constante.DATE_FORMATT);

            // date now
            Date dateNow = new Date();
            // format Date & hour
            String Date = Utility.formatDate2String(dateNow, Constante.DATE_FORMATT);
            String heure = Utility.formatDate2String(dateNow, "HH:mm:ss");

            // content replace params
            content = content.replace("numero_de_compte_debite", numero_de_compte_debite);
            content = content.replace("numero_de_compte_benef", numero_de_compte_benef);

            content = content.replace("Nom_bénéficiaire", Nom_bénéficiaire);
            content = content.replace("Libelle_operation", Libelle_operation);
            content = content.replace("Date_execution_virement", Date_execution_virement);
            content = content.replace("Etat_virement", Etat_virement);
            content = content.replace("Date_de_fin_du_virement_permanent",
                    Date_de_fin_du_virement_permanent);
            content = content.replace("Montant_virement", Montant_virement);
            content = content.replace("Date_", Date);
            content = content.replace("Heure_", heure);

            String Subject = "Avis d'opération virement permanent";
            String to = email;

            // send mail
            boolean send = Mailer.send(to, Subject, content);
            addNotifWhenSend(send, tier, ctrBAD, numDLG, canal, dateNow, email, idVirementPerm);

        }
    }

